python3 -c "
import json
d = json.load(open('/app/trial/agent/trajectory.json'))
steps = d['steps']
for i, s in enumerate(steps):
    msg = s.get('message', {})
    src = s.get('source')
    role = msg.get('role') if isinstance(msg, dict) else None
    content = msg.get('content') if isinstance(msg, dict) else None
    summary = ''
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict):
                t = c.get('type')
                if t == 'text':
                    parts.append('TEXT: ' + c.get('text','')[:200])
                elif t == 'tool_use':
                    parts.append(f'TOOLUSE {c.get(\"name\")}: ' + json.dumps(c.get('input',{}))[:300])
                elif t == 'tool_result':
                    cont = c.get('content')
                    if isinstance(cont, list):
                        cont = ' '.join([x.get('text','')[:200] for x in cont if isinstance(x,dict)])
                    parts.append('TOOLRESULT: ' + str(cont)[:200])
        summary = ' | '.join(parts)
    elif isinstance(content, str):
        summary = content[:200]
    print(i, src, role, summary[:400])
    print('---')
"

